-- Run these statements manually in your PostgreSQL/Supabase SQL editor.
-- No EF Core migration is included for this feature.

ALTER TABLE "MASTER_REPORT"
    ADD COLUMN IF NOT EXISTS "PRIORITY" varchar(16) NOT NULL DEFAULT 'Normal';

CREATE TABLE IF NOT EXISTS "USER_NOTIFICATION" (
    "NOTIFICATION_ID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "USER_ID" integer NOT NULL REFERENCES "MASTER_USER" ("USER_ID") ON DELETE CASCADE,
    "REPORT_ID" integer NOT NULL REFERENCES "MASTER_REPORT" ("REPORT_ID") ON DELETE CASCADE,
    "TITLE" varchar(250) NOT NULL,
    "MESSAGE" varchar(1000) NOT NULL,
    "PRIORITY" varchar(16) NOT NULL DEFAULT 'Normal',
    "REPORT_URL" varchar(1000) NOT NULL,
    "IS_READ" boolean NOT NULL DEFAULT false,
    "READ_DATE" timestamp without time zone NULL,
    "ACKNOWLEDGED_DATE" timestamp without time zone NULL,
    "ACKNOWLEDGED_BY" integer NULL REFERENCES "MASTER_USER" ("USER_ID") ON DELETE SET NULL,
    "CREATED_DATE" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS "IX_USER_NOTIFICATION_USER_UNREAD"
    ON "USER_NOTIFICATION" ("USER_ID", "IS_READ", "CREATED_DATE" DESC);

CREATE TABLE IF NOT EXISTS "WEB_PUSH_SUBSCRIPTION" (
    "SUBSCRIPTION_ID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "USER_ID" integer NOT NULL REFERENCES "MASTER_USER" ("USER_ID") ON DELETE CASCADE,
    "ENDPOINT" text NOT NULL UNIQUE,
    "P256DH" text NOT NULL,
    "AUTH" text NOT NULL,
    "CREATED_DATE" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UPDATED_DATE" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS "IX_WEB_PUSH_SUBSCRIPTION_USER"
    ON "WEB_PUSH_SUBSCRIPTION" ("USER_ID");

